antiPatterns.example:
// Avoid: no dimensions
<Image src={src} alt={alt} />

// Prefer: real aspect ratio
<Image src={src} alt={alt} width={1200} height={630} />

// Avoid: every card eager
items.map((item) => <Image priority ... />)

// Prefer: first item only
items.map((item, index) => <Image priority={index === 0} ... />)
